{{!-- Styling parameters: class --}}
{{#with this as |ghostcnStyles|}}
<span class="ghcn-ui-badge{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" data-variant="{{#match variant "secondary"}}secondary{{else}}{{#match variant "outline"}}outline{{else}}{{#match variant "destructive"}}destructive{{else}}default{{/match}}{{/match}}{{/match}}" data-size="{{#match size "sm"}}sm{{else}}{{#match size "lg"}}lg{{else}}default{{/match}}{{/match}}">{{#if text}}{{text}}{{else}}Label{{/if}}</span>
{{/with}}

.ghcn-ui-badge { box-sizing: border-box; font-family: inherit; font-size: 16px; line-height: 1.5; color: var(--foreground); }
.ghcn-ui-badge, .ghcn-ui-badge * { box-sizing: border-box; }
.ghcn-ui-badge:where([data-size="sm"]) { font-size: 14px; }
.ghcn-ui-badge:where([data-size="lg"]) { font-size: 18px; }
.ghcn-ui-badge:focus-visible, .ghcn-ui-badge :focus-visible { outline: 2px solid var(--ring); outline-offset: 3px; }
.ghcn-ui-badge { display: inline-flex; align-items: center; padding: .125em .625em; border: 1px solid transparent; border-radius: 999px; background: var(--primary); color: var(--primary-foreground); font-weight: 600; }
.ghcn-ui-badge:where([data-variant="secondary"]) { background: var(--secondary); color: var(--secondary-foreground); }
.ghcn-ui-badge:where([data-variant="outline"]) { background: transparent; color: var(--foreground); border-color: var(--border); }
.ghcn-ui-badge:where([data-variant="destructive"]) { background: var(--destructive); color: var(--destructive-foreground); }
